"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[7788],{9858(e){e.exports=JSON.parse('{"tag":{"label":"Memoization","permalink":"/concepts/tags/memoization","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"algorithm-design-paradigms/dynamic-programming","title":"Dynamic Programming","description":"Divide and conquer breaks a problem into subproblems and combines their solutions. It works beautifully when the subproblems are independent. But we saw in the divide and conquer chapter that the naive recursive Fibonacci solves the same subproblems again and again, and becomes exponential. Dynamic programming keeps the idea of solving a problem through its subproblems, but solves each subproblem only once, storing its solution in a table for later use.","permalink":"/concepts/algorithm-design-paradigms/dynamic-programming"},{"id":"algorithm-design-paradigms/exercises-dynamic-programming","title":"Exercises: Dynamic Programming","description":"These exercises review the two lessons on dynamic programming. For each problem, follow the design steps of the first lesson the solutions are grouped at the end of the page.","permalink":"/concepts/algorithm-design-paradigms/exercises-dynamic-programming"}],"unlisted":false}}')}}]);